export class AdminDeliveryZonesPage {
  private readonly api=inject(ApiService);
  readonly zones=signal<DeliveryZone[]>([]);
  readonly loading=signal(true);
  readonly saving=signal(false);
  readonly open=signal(false);
  readonly editingId=signal<string|null>(null);
  readonly notice=signal('');
  readonly error=signal('');
  draft={code:'',name:'',fee:0};
  constructor(){void this.load();}
  async load():Promise<void>{this.loading.set(true);try{this.zones.set(await firstValueFrom(this.api.get<DeliveryZone[]>('/api/admin/delivery-zones')));}catch{this.notice.set('Delivery zones could not be loaded.');this.error.set('1');}finally{this.loading.set(false);}}
  openCreate():void{this.editingId.set(null);this.draft={code:'',name:'',fee:0};this.open.set(true);}
  edit(zone:DeliveryZone):void{this.editingId.set(zone.id);this.draft={code:zone.code,name:zone.name,fee:zone.fee};this.open.set(true);}
  async save(form:{invalid:boolean|null}):Promise<void>{if(form.invalid)return;this.saving.set(true);try{const body={...this.draft,code:this.draft.code.toUpperCase()};if(this.editingId())await firstValueFrom(this.api.put(`/api/admin/delivery-zones/${this.editingId()}`,body));else await firstValueFrom(this.api.post('/api/admin/delivery-zones',body));this.notice.set(this.editingId()?'Delivery zone updated.':'Delivery zone created.');this.error.set('');this.open.set(false);await this.load();}catch(e){this.notice.set(apiError(e,'Could not save this zone. Check its code is unique.'));this.error.set('1');}finally{this.saving.set(false);}}
  async toggle(zone:DeliveryZone):Promise<void>{try{await firstValueFrom(this.api.patch<void>(`/api/admin/delivery-zones/${zone.id}/active`,!zone.isActive));this.notice.set(`Zone ${!zone.isActive?'activated':'deactivated'}.`);this.error.set('');await this.load();}catch(e){this.notice.set(apiError(e,'Could not change delivery zone status.'));this.error.set('1');}}
}

